// UTF-16 <-> UTF-8.  Archive formats store names as UTF-16; on Linux we keep
// them as UTF-8 everywhere else.  Unpaired surrogates are mapped through the
// WTF-8 style encoding so that a name survives a round trip.

std::string Utf16ToUtf8(const UInt16 *src, size_t len) {
  std::string out;
  out.reserve(len + len / 2);
  for (size_t i = 0; i < len; i++) {
    UInt32 c = src[i];
    if (c >= 0xD800 && c < 0xDC00 && i + 1 < len) {
      UInt32 c2 = src[i + 1];
      if (c2 >= 0xDC00 && c2 < 0xE000) {
        c = 0x10000 + ((c - 0xD800) << 10) + (c2 - 0xDC00);
        i++;
      }
    }
    if (c < 0x80) {
      out += (char)c;
    } else if (c < 0x800) {
      out += (char)(0xC0 | (c >> 6));
      out += (char)(0x80 | (c & 0x3F));
    } else if (c < 0x10000) {
      out += (char)(0xE0 | (c >> 12));
      out += (char)(0x80 | ((c >> 6) & 0x3F));
      out += (char)(0x80 | (c & 0x3F));
    } else {
      out += (char)(0xF0 | (c >> 18));
      out += (char)(0x80 | ((c >> 12) & 0x3F));
      out += (char)(0x80 | ((c >> 6) & 0x3F));
      out += (char)(0x80 | (c & 0x3F));
    }
  }
  return out;
}

void Utf8ToUtf16(const std::string &src, std::vector<UInt16> &dest) {
  dest.clear();
  dest.reserve(src.size());
  size_t i = 0, n = src.size();
  while (i < n) {
    Byte b = (Byte)src[i];
    UInt32 c;
    unsigned extra;
    if (b < 0x80)        { c = b;         extra = 0; }
    else if (b < 0xC0)   { c = b;         extra = 0; }  // stray continuation
    else if (b < 0xE0)   { c = b & 0x1F;  extra = 1; }
    else if (b < 0xF0)   { c = b & 0x0F;  extra = 2; }
    else if (b < 0xF8)   { c = b & 0x07;  extra = 3; }
    else                 { c = b;         extra = 0; }
    if (i + extra >= n) extra = 0;
    bool bad = false;
    for (unsigned k = 1; k <= extra; k++) {
      Byte cb = (Byte)src[i + k];
      if ((cb & 0xC0) != 0x80) { bad = true; break; }
      c = (c << 6) | (cb & 0x3F);
    }
    if (bad) { c = b; extra = 0; }
    i += extra + 1;
    if (c >= 0x10000) {
      if (c > 0x10FFFF) c = 0xFFFD;
      c -= 0x10000;
      dest.push_back((UInt16)(0xD800 + (c >> 10)));
      dest.push_back((UInt16)(0xDC00 + (c & 0x3FF)));
    } else {
      dest.push_back((UInt16)c);
    }
  }
}

bool StrEqNoCase(const char *a, const char *b) {
  for (;; a++, b++) {
    int ca = tolower((unsigned char)*a), cb = tolower((unsigned char)*b);
    if (ca != cb) return false;
    if (ca == 0) return true;
  }
}

bool StrEqNoCase(const std::string &a, const char *b) { return StrEqNoCase(a.c_str(), b); }

std::string ToLower(const std::string &s) {
  std::string r(s);
  for (size_t i = 0; i < r.size(); i++) r[i] = (char)tolower((unsigned char)r[i]);
  return r;
}

std::string ToUpper(const std::string &s) {
  std::string r(s);
  for (size_t i = 0; i < r.size(); i++) r[i] = (char)toupper((unsigned char)r[i]);
  return r;
}
